from pathlib import Path
import xml.etree.ElementTree as ET

root = Path(".superpowers/sdd/2026-09-10-sec-retention-inventory-and-helper-cleanup/task2-state/m1/artifacts")
results = {}
nodes = {}
for path in sorted(root.glob("*.xml")):
    document = ET.parse(path).getroot()
    suites = document.findall("testsuite")
    cases = document.findall(".//testcase")
    assert len({case.get("classname") for case in cases}) == 1
    nodes[path.stem] = {case.get("name") for case in cases}
    assert len(nodes[path.stem]) == len(cases)
    results[path.stem] = {
        **{key: sum(int(suite.get(key, "0")) for suite in suites) for key in ("tests", "failures", "errors", "skipped")},
        "failed_nodes": [case.get("name") for case in cases if case.find("failure") is not None],
    }
added = nodes["final"] - nodes["baseline-copy"]
removed = nodes["baseline-copy"] - nodes["final"]
assert not removed
assert added == {
    "test_retained_journal_does_not_export_legacy_codec_helpers[_json]",
    "test_retained_journal_does_not_export_legacy_codec_helpers[_sha]",
}
owner_failures = added | {
    "test_journal_consumers_import_the_neutral_codec_directly[lifecycle_web_store-names6]",
}
consumer_failure = "test_journal_consumers_import_the_neutral_codec_directly[lifecycle_investigation.store-names0]"
for label in ("aliases-red", "definitions-red"):
    assert set(results[label]["failed_nodes"]) == owner_failures
for label in ("legacy-import-use-red", "legacy-attribute-use-red"):
    assert set(results[label]["failed_nodes"]) == owner_failures | {consumer_failure}
for label, result in results.items():
    assert result["errors"] == result["skipped"] == 0
    if not label.endswith("-red"):
        assert result["failures"] == 0
assert nodes["restored-copy"] == nodes["final"]
print(json.dumps({"results": results, "accounting": {"baseline": len(nodes["baseline-copy"]), "final": len(nodes["final"]), "added": sorted(added), "removed": sorted(removed)}}, indent=2))
'
